using System.Numerics;

namespace ErikasLab.Engine;

/// <summary>
/// Phase 2S: one static vertex. <see cref="TexCoord"/> is generated by
/// <see cref="MeshFactory"/> as a deterministic planar mapping per primitive
/// (unit-normalized per face for the shared unit box/prism, local meters for
/// the fixed-size ground planes); the renderer scales it to world repeats via
/// <see cref="MeshFactory.ApplyUvScale"/> when a material binds a texture.
/// </summary>
public readonly record struct MeshVertex(Vector3 Position, Vector3 Normal, ColorRgba Color, Vector2 TexCoord);

public sealed class MeshData
{
    public MeshData(IReadOnlyList<MeshVertex> vertices, IReadOnlyList<int> indices)
    {
        ArgumentNullException.ThrowIfNull(vertices);
        ArgumentNullException.ThrowIfNull(indices);

        if (vertices.Count == 0)
        {
            throw new ArgumentException("A mesh must contain at least one vertex.", nameof(vertices));
        }

        if (indices.Count == 0 || indices.Count % 3 != 0)
        {
            throw new ArgumentException("A triangle-list mesh must contain a non-zero multiple of three indices.", nameof(indices));
        }

        if (indices.Any(index => index < 0 || index >= vertices.Count))
        {
            throw new ArgumentException("Mesh indices must reference an existing vertex.", nameof(indices));
        }

        Vertices = vertices.ToArray();
        Indices = indices.ToArray();
    }

    public IReadOnlyList<MeshVertex> Vertices { get; }

    public IReadOnlyList<int> Indices { get; }
}
